-- Apply after database.sql. Amounts are stored in centavos; browser prices are never trusted.
BEGIN;
CREATE TABLE subscriptions (id text PRIMARY KEY, representative_id text NOT NULL REFERENCES representatives(id), users_count integer NOT NULL CHECK(users_count > 0), period_months integer NOT NULL CHECK(period_months IN (1,3,6,12)), status text NOT NULL CHECK(status IN ('pending_payment','active','past_due','cancelled','expired')), renews_automatically boolean NOT NULL DEFAULT false, provider_subscription_id text UNIQUE, provider_status text, contracted_amount_cents integer NOT NULL CHECK(contracted_amount_cents > 0), currency char(3) NOT NULL DEFAULT 'BRL', current_period_ends_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE billing_invoices (id text PRIMARY KEY, representative_id text NOT NULL REFERENCES representatives(id), subscription_id text REFERENCES subscriptions(id), amount_cents integer NOT NULL CHECK(amount_cents > 0), currency char(3) NOT NULL DEFAULT 'BRL', provider text NOT NULL DEFAULT 'mercado_pago', provider_preference_id text UNIQUE, provider_payment_id text UNIQUE, provider_authorized_payment_id text UNIQUE, status text NOT NULL CHECK(status IN ('pending','approved','rejected','cancelled','refunded')), payment_method text, created_at timestamptz NOT NULL DEFAULT now(), paid_at timestamptz, entitlement_applied_at timestamptz);
CREATE TABLE billing_webhook_events (provider_event_id text PRIMARY KEY, received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE billing_entitlement_outbox (invoice_id text PRIMARY KEY REFERENCES billing_invoices(id), representative_id text NOT NULL REFERENCES representatives(id), firebase_uid text, access_until timestamptz NOT NULL, device_limit integer NOT NULL CHECK(device_limit BETWEEN 1 AND 1000), period_months integer NOT NULL CHECK(period_months IN (1,3,6,12)), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','delivered')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), last_error text, created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz);
CREATE INDEX billing_entitlement_pending ON billing_entitlement_outbox(status,created_at) WHERE status='pending';
CREATE INDEX billing_invoices_rep ON billing_invoices(representative_id, created_at DESC);
COMMIT;
